from datetime import date, timedelta


def is_business_day(d: date, holidays=()) -> bool:
    return d.weekday() < 5 and d not in set(holidays)


def adjust_business_day(d: date, holidays=(), convention: str = "modified_following") -> date:
    if not isinstance(convention, str):
        raise ValueError("invalid convention")
    conv = convention.lower()
    if conv not in ("following", "modified_following", "preceding"):
        raise ValueError("invalid convention")
    holiday_set = set(holidays)
    if d.weekday() < 5 and d not in holiday_set:
        return d
    if conv == "preceding":
        cur = d
        while not (cur.weekday() < 5 and cur not in holiday_set):
            cur -= timedelta(days=1)
        return cur
    # following / modified_following: find next business day
    cur = d
    while not (cur.weekday() < 5 and cur not in holiday_set):
        cur += timedelta(days=1)
    if conv == "following":
        return cur
    # modified_following
    if (cur.year, cur.month) != (d.year, d.month):
        prev = d
        while not (prev.weekday() < 5 and prev not in holiday_set):
            prev -= timedelta(days=1)
        return prev
    return cur


def add_business_days(start: date, n: int, holidays=()) -> date:
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError("n must be an int")
    if n == 0:
        return start
    holiday_set = set(holidays)
    step = timedelta(days=1) if n > 0 else timedelta(days=-1)
    remaining = abs(n)
    cur = start
    while remaining > 0:
        cur += step
        if cur.weekday() < 5 and cur not in holiday_set:
            remaining -= 1
    return cur
